	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/fiscal/emisor", wrapper.EmisorFiscal)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/admin/facturacion/emisor", wrapper.GuardarEmisorFiscal)
